frappe.ui.form.on('Repair Notification', {
  onload(frm) {
    // ทำเฉพาะตอนสร้างเอกสารใหม่ และยังไม่มีค่า
    if (frm.is_new()) {
      // ตั้งวันที่ถ้ายังไม่ได้กำหนด
      if (!frm.doc.date_notification) {
        frm.set_value('date_notification', frappe.datetime.get_today());
      }
      // ตั้งเวลาถ้ายังไม่ได้กำหนด
      if (!frm.doc.time_notification) {
        frm.set_value('time_notification', frappe.datetime.now_time());
      }
    }

    // เติมรายการตรวจเฉพาะตอนเอกสารใหม่ หรือเมื่อยังไม่มีแถว
    populate_tb2_if_empty(frm);
  },

  // กันลืมกรอกก่อนบันทึก (ไม่เขียนทับถ้ามีแล้ว)
  before_save(frm) {
    if (!frm.doc.date_notification) {
      frm.set_value('date_notification', frappe.datetime.get_today());
    }
    if (!frm.doc.time_notification) {
      frm.set_value('time_notification', frappe.datetime.now_time());
    }
  }
});


function populate_tb2_if_empty(frm) {
  if (!frm.doc.tb2 || frm.doc.tb2.length === 0) {
    const list = [
      "1.ระยะเวลาการให้บริการ (ตรงเวลานัดหมาย,ความเหมาะสมของระยะเวลาที่ใช้ปฏิบัติงานจนงานแล้วเสร็จ)",
      "2.การให้บริการของเจ้าหน้าที่ (สุภาพ,กระตือรือร้น,เอาใจใส่,รับผิดชอบ)",
      "3.งานเสร็จแล้ว,ครบถ้วน,ได้คุณภาพ,ตรงตามความต้องการ"
    ];

    list.forEach(text => {
      const row = frm.add_child('tb2');
      row.list = text;
    });

    frm.refresh_field('tb2');
  }
}

/******************************
 * Repair Notification – Client Script
 * ทำให้ chk1/chk2/chk3 ในแต่ละแถวของตาราง tb2 เลือกได้ทีละ 1 ช่อง
 ******************************/

// รายชื่อฟิลด์ "checkbox" ที่ต้อง mutual-exclusive
const RN_MUTEX_FIELDS = ['chk1', 'chk2', 'chk3'];

/** เคลียร์ช่องอื่นๆ ในแถวเดียวกันให้เหลือเฉพาะ field ที่เพิ่งติ๊ก */
function rn_set_exclusive(cdt, cdn, picked_field) {
  const row = locals[cdt][cdn];
  RN_MUTEX_FIELDS.forEach(f => {
    if (f !== picked_field && row[f]) {
      frappe.model.set_value(cdt, cdn, f, 0);
    }
  });
}

/** ปรับข้อมูลให้ถูกต้องก่อนบันทึก (กันกรณีมีหลายช่องเป็น 1 จากการ import/แก้ไขเก่า) */
function rn_fix_before_save(frm) {
  (frm.doc.tb2 || []).forEach(r => {
    // ทำให้ค่าของ checkbox เป็น 0/1 เท่านั้น
    RN_MUTEX_FIELDS.forEach(f => { r[f] = r[f] ? 1 : 0; });

    const selected = RN_MUTEX_FIELDS.filter(f => r[f] === 1);
    if (selected.length > 1) {
      const keep = selected[0]; // เก็บตัวแรกไว้ ที่เหลือปิด
      RN_MUTEX_FIELDS.forEach(f => { if (f !== keep) r[f] = 0; });
    }
  });
}

/* ---------- Events บน Child Doctype ---------- */
// ชื่อ Doctype ลูกต้องตรงกับของจริง
frappe.ui.form.on('Repair Notification Assessment Table', {
  // เมื่อมีการติ๊ก chk1/2/3 ให้ล้างช่องอื่นในแถวเดียวกันทันที
  chk1(frm, cdt, cdn) {
    if (locals[cdt][cdn].chk1) rn_set_exclusive(cdt, cdn, 'chk1');
  },
  chk2(frm, cdt, cdn) {
    if (locals[cdt][cdn].chk2) rn_set_exclusive(cdt, cdn, 'chk2');
  },
  chk3(frm, cdt, cdn) {
    if (locals[cdt][cdn].chk3) rn_set_exclusive(cdt, cdn, 'chk3');
  }
});

/* ---------- Hook บนฟอร์มแม่ ---------- */
frappe.ui.form.on('Repair Notification', {
  // ก่อนบันทึก ตรวจทานให้เหลือได้มากสุด 1 ช่องต่อแถว
  before_save(frm) {
    rn_fix_before_save(frm);
  },

  // (ออปชัน) เมื่อโหลดฟอร์มมา ถ้าเคยมีข้อมูลเก่าที่ติ๊กมากกว่า 1 ช่องในแถว จะทำความสะอาดให้
  onload(frm) {
    rn_fix_before_save(frm);
  }
});

/******************************************
 * Repair Notification – mutually exclusive
 * chk_urgent ↔ chk_urgent_no (เลือกได้ทีละ 1)
 ******************************************/

frappe.ui.form.on('Repair Notification', {
  // เมื่อเปลี่ยนค่า chk_urgent ให้ปิดอีกช่องทันที
  chk_urgent(frm) {
    if (frm.doc.chk_urgent) {
      frm.set_value('chk_urgent_no', 0);
    }
  },

  // เมื่อเปลี่ยนค่า chk_urgent_no ให้ปิดอีกช่องทันที
  chk_urgent_no(frm) {
    if (frm.doc.chk_urgent_no) {
      frm.set_value('chk_urgent', 0);
    }
  },

  // กันข้อมูลเก่า/การ import ที่อาจติ๊กทั้งสองพร้อมกัน
  onload(frm) {
    fix_exclusive(frm);
  },

  // ตรวจความถูกต้องก่อนบันทึก (กันทั้งสองเป็น 1)
  before_save(frm) {
    fix_exclusive(frm);

    // (ออปชัน) ถ้าต้อง "บังคับเลือกอย่างน้อย 1 ช่อง" ให้เปิดคอมเมนต์ด้านล่าง
    // if (!frm.doc.chk_urgent && !frm.doc.chk_urgent_no) {
    //   frappe.throw(__('กรุณาเลือก ด่วน หรือ ไม่ด่วน อย่างน้อย 1 ตัวเลือก'));
    // }
  }
});

// ตัวช่วย: ถ้าบังเอิญเป็น 1 ทั้งคู่ ให้คงค่าไว้เฉพาะตัวที่เพิ่งแก้/หรือเก็บ chk_urgent
function fix_exclusive(frm) {
  const a = !!frm.doc.chk_urgent ? 1 : 0;
  const b = !!frm.doc.chk_urgent_no ? 1 : 0;

  if (a && b) {
    // ค่าเริ่ม ถ้าชนกัน ให้คง chk_urgent ไว้ แล้วปิดอีกตัว
    frm.set_value('chk_urgent_no', 0);
  }
}


/**************************************
 * Repair Notification – Client Script
 * บังคับให้ติ๊กได้ทีละ 1 ค่า:
 *   - chk_have
 *   - chk_no_have
 *   - chk_unsure
 **************************************/

// รายชื่อฟิลด์ checkbox ที่ต้อง exclusive
var EXCLUSIVE_CHECKS = ["chk_have", "chk_no_have", "chk_unsure"];

/** เคลียร์ช่องอื่น ๆ เมื่อมีการเปลี่ยนแปลงช่องหนึ่ง */
function enforce_single_choice(frm, changed_field) {
  // ถ้าช่องที่เพิ่งเปลี่ยนเป็น true -> ปิดตัวอื่น
  if (frm.doc[changed_field]) {
    EXCLUSIVE_CHECKS.forEach(function (f) {
      if (f !== changed_field && frm.doc[f]) {
        frm.set_value(f, 0);
      }
    });
  } else {
    // ถ้าผู้ใช้ uncheck ช่องนั้นและเหลือ none -> อนุญาตให้ว่างได้ชั่วคราว
    // (จะตรวจซ้ำอีกครั้งตอน validate)
  }
  frm.refresh_fields(EXCLUSIVE_CHECKS);
}

/** นับจำนวนที่ถูกติ๊ก */
function count_checked(frm) {
  return EXCLUSIVE_CHECKS.reduce(function (acc, f) {
    return acc + (frm.doc[f] ? 1 : 0);
  }, 0);
}

frappe.ui.form.on('Repair Notification', {
  onload: function (frm) {
    // ถ้าเอกสารใหม่และยังไม่เลือกอะไรเลย จะตั้ง default เป็น 'unsure' ก็ได้ (เลือกใช้หรือคอมเมนต์ทิ้งได้)
    if (frm.is_new() && count_checked(frm) === 0) {
      frm.set_value('chk_unsure', 1);
      frm.refresh_fields(EXCLUSIVE_CHECKS);
    }
  },

  // ผูก event กับแต่ละช่อง
  chk_have: function (frm) {
    enforce_single_choice(frm, 'chk_have');
  },
  chk_no_have: function (frm) {
    enforce_single_choice(frm, 'chk_no_have');
  },
  chk_unsure: function (frm) {
    enforce_single_choice(frm, 'chk_unsure');
  },

  validate: function (frm) {
    var n = count_checked(frm);
    if (n > 1) {
      frappe.throw(__('สามารถเลือกได้เพียง 1 ค่าเท่านั้น'));
    }
  }
});

/********************************************
 * Repair Notification – Client Script
 * Logic:
 * 1) chk_in / chk_out  => exclusive (เลือกได้ทีละ 1)
 * 2) ถ้าเลือก chk_out  => ล้าง chk_no_add / chk_add
 * 3) ถ้าเลือก chk_in   => ต้องมี chk_no_add หรือ chk_add อย่างใดอย่างหนึ่ง
 * 4) chk_no_add / chk_add => exclusive (เลือกได้ทีละ 1)
 ********************************************/

var INOUT_FIELDS = ["chk_in", "chk_out"];
var ADD_FIELDS   = ["chk_no_add", "chk_add"];

/** คืนจำนวนช่องที่ถูกติ๊กในกลุ่มฟิลด์ */
function count_checked_in(frm, fields) {
  return fields.reduce(function (acc, f) { return acc + (frm.doc[f] ? 1 : 0); }, 0);
}

/** ทำให้ช่องในกลุ่ม exclusive: ถ้า changed ติ๊ก => ปิดช่องอื่นในกลุ่ม */
function make_exclusive(frm, fields, changed) {
  if (!frm.doc[changed]) return; // เฉพาะกรณีติ๊กเป็น true
  fields.forEach(function (f) {
    if (f !== changed && frm.doc[f]) frm.set_value(f, 0);
  });
  frm.refresh_fields(fields);
}

/** ล้างกลุ่มฟิลด์ (ตั้งค่า 0) */
function clear_group(frm, fields) {
  fields.forEach(function (f) { if (frm.doc[f]) frm.set_value(f, 0); });
  frm.refresh_fields(fields);
}

frappe.ui.form.on("Repair Notification", {
  // ไม่กำหนด default เพื่อให้ผู้ใช้เลือกเอง

  // ====== IN / OUT ======
  chk_in: function (frm) {
    if (frm.doc.chk_in) {
      // เลือก IN -> ปิด OUT
      make_exclusive(frm, INOUT_FIELDS, "chk_in");
      // ไม่บังคับเลือก ADD ตอนนี้ ปล่อยให้ผู้ใช้เลือกเอง
      // (แต่ถ้ายังไม่ได้เลือกสักอัน จะโดนบังคับตอน validate)
    } else {
      // เอา IN ออก ถ้าไม่มีใครเลือกเลย ให้เตือนแค่ตอน validate ก็พอ
    }
  },

  chk_out: function (frm) {
    if (frm.doc.chk_out) {
      // เลือก OUT -> ปิด IN และล้าง ADD ทั้งคู่
      make_exclusive(frm, INOUT_FIELDS, "chk_out");
      clear_group(frm, ADD_FIELDS);
    }
  },

  // ====== NO_ADD / ADD ======
  chk_no_add: function (frm) {
    if (frm.doc.chk_no_add) {
      // กลุ่ม ADD ต้อง exclusive
      make_exclusive(frm, ADD_FIELDS, "chk_no_add");
      // ถ้ามาติ๊กฝั่งนี้ แปลว่าเป็นกรณี IN
      if (!frm.doc.chk_in) frm.set_value("chk_in", 1);
      if (frm.doc.chk_out) frm.set_value("chk_out", 0);
      frm.refresh_fields(INOUT_FIELDS);
    } else {
      // เอาออกแล้วถ้าเหลือว่างทั้งคู่ จะไปเช็คตอน validate
    }
  },

  chk_add: function (frm) {
    if (frm.doc.chk_add) {
      make_exclusive(frm, ADD_FIELDS, "chk_add");
      if (!frm.doc.chk_in) frm.set_value("chk_in", 1);
      if (frm.doc.chk_out) frm.set_value("chk_out", 0);
      frm.refresh_fields(INOUT_FIELDS);
    }
  },


});

/********************************************
 * Repair Notification – Script #2
 * CAN_USED / CAN_NOT_USED (แยกจากชุดที่ 1)
 ********************************************/

(function(){
  var CANUSE = ["chk_can_not_used", "chk_can_used"];
  var REQUIRE_CANUSE = true; // ถ้าไม่อยากบังคับให้เลือก 1 ช่อง ให้เปลี่ยนเป็น false

  function rn2_count(frm, fields){
    return fields.reduce(function(acc, f){ return acc + (frm.doc[f] ? 1 : 0); }, 0);
  }
  function rn2_exclusive(frm, fields, changed){
    if (!frm.doc[changed]) return;
    fields.forEach(function(f){ if (f !== changed && frm.doc[f]) frm.set_value(f, 0); });
    frm.refresh_fields(fields);
  }

  frappe.ui.form.on("Repair Notification", {
    chk_can_not_used: function(frm){
      if (frm.doc.chk_can_not_used){
        rn2_exclusive(frm, CANUSE, "chk_can_not_used");
      }
    },
    chk_can_used: function(frm){
      if (frm.doc.chk_can_used){
        rn2_exclusive(frm, CANUSE, "chk_can_used");
      }
    },
    
  });
})();


// ดึงชื่อจาก User ที่ login อยู่
frappe.ui.form.on('Repair Notification', {
    onload: function(frm) {
        if (frm.is_new()) {
            // รับอีเมลของผู้ใช้ปัจจุบัน
            let user_email = frappe.session.user;

            // เรียกใช้ฟังก์ชันฝั่งเซิร์ฟเวอร์เพื่อรับข้อมูลผู้ใช้
            frappe.call({
                method: 'frappe.client.get',
                args: {
                    doctype: 'User',
                    name: user_email
                },
                callback: function(response) {
                    if (response.message) {
                        let user_doc = response.message;
                        // เข้าถึงฟิลด์ full_name
                        let full_name = user_doc.full_name;
                        
                        // ตั้งค่าในแบบฟอร์มกำหนดการทำงาน
                        frm.set_value('fullname', full_name);
                        
                        // รีเฟรชฟิลด์เพื่อให้แน่ใจว่ามีการอัปเดตแล้ว
                        frm.refresh_field('fullname');
                       
                    }
                }
            });
        }
    }
});

frappe.ui.form.on('Repair Notification', {

    validate(frm) {
        check_limit(frm);
    },

    before_save(frm) {
        check_limit(frm);
    },

    refresh(frm) {
        disable_add_when_full(frm);
    }
});


function check_limit(frm) {
    let max = 8;

    if ((frm.doc.repair_notification_table || []).length > max) {
        frappe.throw('เพิ่มได้ไม่เกิน 8 รายการ');
    }
}


function disable_add_when_full(frm) {
    let grid = frm.get_field('repair_notification_table').grid;

    // เก็บของเดิม
    if (!grid._add_row_original) {
        grid._add_row_original = grid.add_new_row;
    }

    grid.add_new_row = function () {
        if ((frm.doc.repair_notification_table || []).length >= 8) {
            frappe.msgprint('เพิ่มได้ไม่เกิน 8 รายการ');
            return;
        }
        grid._add_row_original();
    };
}

frappe.ui.form.on('Repair Notification', {
    refresh(frm) {

        let grid = frm.get_field('repair_notification_table').grid;

        if (!grid._limited) {
            grid._limited = true;

            let original_add = grid.add_new_row;

            grid.add_new_row = function () {
                original_add.call(this);

                let rows = frm.doc.repair_notification_table || [];

                if (rows.length > 8) {
                    // ลบแถวสุดท้าย
                    frm.doc.repair_notification_table.splice(8);

                    frm.refresh_field('repair_notification_table');

                    frappe.msgprint('เพิ่มได้ไม่เกิน 8 รายการ');
                }
            };
        }
    }
});

frappe.ui.form.on('Quotation For Marketing', {
    onload: function(frm) {
        if (frm.is_new() && !frm.doc.coordinator_name) {
            frm.set_value('coordinator_name', frappe.session.user_fullname);
        }
    },

    refresh: function(frm) {
        calculate_all_totals(frm);
    },

    // อีเวนต์เมื่อเปลี่ยนค่าที่ฟิลด์ด้านนอก
    desired_profit: function(frm) { calculate_all_totals(frm); },
    discount: function(frm) { calculate_all_totals(frm); },

    coordinator_name: function(frm) {
        if (frm.doc.coordinator_name) {
            frappe.call({
                method: "frappe.client.get_value",
                args: { 
                    doctype: "Personnel",
                    fieldname: ["nickname", "number_phone", "job_position"],
                    filters: { name: frm.doc.coordinator_name }, 
                },
                callback: function(r) {
                    if (r.message) {
                        if (frm.doc.nickname !== r.message.nickname) frm.set_value("nickname", r.message.nickname);
                        if (frm.doc.number_phone !== r.message.number_phone) frm.set_value("number_phone", r.message.number_phone);
                        if (frm.doc.job_position !== r.message.job_position) frm.set_value("job_position", r.message.job_position);


                    }
                }
            });
        }
    }
});

// ตารางที่ 1: รายการต้นทุนหลัก (Table 1)
frappe.ui.form.on('Quotation For Marketing Table', {
    cost_price: function(frm) { calculate_all_totals(frm); },
    selling_price: function(frm) { calculate_all_totals(frm); },
    quotation_for_marketing_table_remove: function(frm) { calculate_all_totals(frm); }
});

// ตารางที่ 2: รายการค่าใช้จ่ายเพิ่มเติม (Table 2)
frappe.ui.form.on('Quotation For Marketing Table2', {
    cost_price: function(frm) { calculate_all_totals(frm); },
    quotation_for_marketing_table2_add: function(frm) { calculate_all_totals(frm); },
    quotation_for_marketing_table2_remove: function(frm) { calculate_all_totals(frm); }
});

// --- ฟังก์ชันคำนวณหลัก (Centralized Logic) ---
var calculate_all_totals = function(frm) {
    // --- ส่วนที่ 1: คำนวณตารางหลัก (Table 1) ---
    let total_cost_t1 = 0;
    let total_selling_t1 = 0;

    (frm.doc.quotation_for_marketing_table || []).forEach(row => {
        total_cost_t1 += flt(row.cost_price);
        total_selling_t1 += flt(row.selling_price);
    });

    // อัปเดตฟิลด์ยอดรวมตาราง 1 (ถ้าค่าเปลี่ยน)
    if (flt(frm.doc.total_cost_price) !== total_cost_t1) frm.set_value('total_cost_price', total_cost_t1);
    if (flt(frm.doc.total_selling_price) !== total_selling_t1) frm.set_value('total_selling_price', total_selling_t1);

    // --- ส่วนที่ 2: คำนวณตารางค่าใช้จ่ายเพิ่มเติม (Table 2) ---
    let total_cost_t2 = 0;
    (frm.doc.quotation_for_marketing_table2 || []).forEach(row => {
        total_cost_t2 += flt(row.cost_price);
    });

    // อัปเดตฟิลด์ total_price (ยอดรวมจาก Table 2)
    if (flt(frm.doc.total_price) !== total_cost_t2) frm.set_value('total_price', total_cost_t2);

    // --- ส่วนที่ 3: คำนวณกำไรและยอดสุทธิ ---

    // 3.1 คำนวณราคาต้นทุนบวกกำไร (Cost + Margin %) จากตารางที่ 1
    let margin_percent = flt(frm.doc.desired_profit);
    let margin_factor = margin_percent / 100;
    let cost_profit_val = 0;

    if (total_cost_t1 > 0 && margin_factor < 1) {
        cost_profit_val = flt(total_cost_t1 / (1 - margin_factor), 2);
    }
    if (flt(frm.doc.cost_price_profit) !== cost_profit_val) frm.set_value('cost_price_profit', cost_profit_val);

    // 3.2 คำนวณยอดสุทธิ (Total)
    // สูตร: ราคาบวกกำไร (T1) + ค่าใช้จ่ายเพิ่ม (T2) - ส่วนลด
    let final_total = flt(cost_profit_val + total_cost_t2 - flt(frm.doc.discount), 2);

    if (flt(frm.doc.total) !== final_total) {
        frm.set_value('total', final_total);
    }
};



